def getCaller(apiKey=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0085000" if __import__("os").path.isdir("./environment_mix/0085000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_ulid():
        # Not a real ULID, but stable, sortable-ish and unique enough for local store usage.
        t_ms = int(time.time() * 1000)
        rand = secrets.token_hex(8)
        return f"01{t_ms:010x}{rand}"

    def _log_call(principal_id, credential, endpoint, status, started_ts):
        # Optional observable service dynamics: append to request_logs if it exists.
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            dur_ms = int((time.time() - started_ts) * 1000)
            row = {
                "id": _gen_ulid(),
                "timestamp": _iso(_now()),
                "endpoint": endpoint,
                "principal_id": principal_id,
                "credential": credential,
                "status": status,
                "latency_ms": dur_ms,
            }
            logs.append(row)
            _save("request_logs.json", logs)

    started = time.time()
    endpoint = "getCaller"

    # Validate input type
    if apiKey is not None and not isinstance(apiKey, str):
        _log_call(None, None, endpoint, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "apiKey must be a string")

    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []

    # Authenticate: If apiKey provided, match against principal.id or a client-visible key field if present.
    principal = None
    cred_used = None
    if apiKey:
        for p in principals:
            if not isinstance(p, dict):
                continue
            if p.get("id") == apiKey:
                principal = p
                cred_used = apiKey
                break
            # allow matching stored plaintext key if a row has it (client-visible), without hashing
            if p.get("kind") == "api_key":
                for k in ("api_key", "key", "value", "token"):
                    if p.get(k) == apiKey:
                        principal = p
                        cred_used = apiKey
                        break
                if principal:
                    break
        if not principal:
            _log_call(None, apiKey, endpoint, "UNAUTHORIZED", started)
            return _err("UNAUTHORIZED", "Invalid API key")
    else:
        # Ambient auth: choose any active principal that can call tools (prefer user/service)
        for p in principals:
            if isinstance(p, dict) and p.get("status") == "active" and p.get("kind") in ("user", "service", "api_key"):
                principal = p
                cred_used = p.get("id")
                break
        if not principal:
            _log_call(None, None, endpoint, "UNAUTHORIZED", started)
            return _err("UNAUTHORIZED", "No authenticated principal available")

    # Quota/rate consumption: best-effort based on request_logs if present.
    usage = {"rate_limit": None, "quota": None}
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        now = _now()
        # rate: last 60s
        win = now - datetime.timedelta(seconds=60)
        count_60s = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("principal_id") != principal.get("id"):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts and ts >= win:
                count_60s += 1
        usage["rate_limit"] = {"window_seconds": 60, "requests_in_window": count_60s}

        # quota: day
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        count_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("principal_id") != principal.get("id"):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts and ts >= day_start:
                count_day += 1
        usage["quota"] = {"period": "day", "requests_used": count_day}

    body = {
        "principal": {
            "id": principal.get("id"),
            "display_name": principal.get("display_name"),
            "kind": principal.get("kind"),
            "default_mode": principal.get("default_mode"),
            "status": principal.get("status"),
            "last_mode_changed_at": principal.get("last_mode_changed_at"),
            "created_at": principal.get("created_at"),
            "updated_at": principal.get("updated_at"),
        },
        "scopes": ["tools:read", "tools:run", "reports:read", "reports:write"],
        "usage": usage,
    }

    _log_call(principal.get("id"), cred_used, endpoint, "OK", started)
    return body

