                "latency_ms": dur_ms,
            })
            _save("request_logs.json", logs)

    def _auth(apiKey_value):
        principals = _load("principals.json")
        if not isinstance(principals, list):
            principals = []
        if apiKey_value is not None and not isinstance(apiKey_value, str):
            return (None, None, _err("VALIDATION_ERROR", "apiKey must be a string"))
        if apiKey_value:
            for p in principals:
                if not isinstance(p, dict):
                    continue
                if p.get("id") == apiKey_value:
                    return (p, apiKey_value, None)
                if p.get("kind") == "api_key":
                    for k in ("api_key", "key", "value", "token"):
                        if p.get(k) == apiKey_value:
                            return (p, apiKey_value, None)
            return (None, apiKey_value, _err("UNAUTHORIZED", "Invalid API key"))
        for p in principals:
            if isinstance(p, dict) and p.get("status") == "active":
                return (p, p.get("id"), None)
        return (None, None, _err("UNAUTHORIZED", "No authenticated principal available"))

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or not tok:
            return None
        pad = "=" * (-len(tok) % 4)
        try:
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    started = time.time()
    endpoint = "listToolRuns"

    # Validate enums/ranges
    status_enum = {"queued", "running", "succeeded", "failed", "cancel_requested", "cancelled"}
    tool_enum = {"nmapScan", "gobuster", "nikto", "generateWordlist", "runJohnTheRipper"}
    mode_enum = {"student", "professional"}

    if status is not None and (not isinstance(status, str) or status not in status_enum):
        _log_call(None, apiKey, endpoint, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "Invalid status")
    if tool is not None and (not isinstance(tool, str) or tool not in tool_enum):
        _log_call(None, apiKey, endpoint, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "Invalid tool")
    if modeEffective is not None and (not isinstance(modeEffective, str) or modeEffective not in mode_enum):
        _log_call(None, apiKey, endpoint, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "Invalid modeEffective")

    ca = _parse_dt(createdAfter) if createdAfter is not None else None
    if createdAfter is not None and ca is None:
        _log_call(None, apiKey, endpoint, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "createdAfter must be RFC3339 date-time")
    cb = _parse_dt(createdBefore) if createdBefore is not None else None
    if createdBefore is not None and cb is None:
        _log_call(None, apiKey, endpoint, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "createdBefore must be RFC3339 date-time")

    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        _log_call(None, apiKey, endpoint, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200")

    if pageToken is not None and not isinstance(pageToken, str):
        _log_call(None, apiKey, endpoint, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "pageToken must be a string")

    principal, cred_used, auth_err = _auth(apiKey)
    if auth_err:
        _log_call(None, cred_used, endpoint, auth_err["error"]["code"], started)
        return auth_err

    tool_runs = _load("tool_runs.json")
    if not isinstance(tool_runs, list):
        tool_runs = []

    # Visibility: only runs owned by principal
    rows = []
    for r in tool_runs:
        if not isinstance(r, dict):
            continue
        if r.get("principal_id") != principal.get("id"):
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool is not None and r.get("tool") != tool:
            continue
        if modeEffective is not None and r.get("mode_effective") != modeEffective:
            continue
        r_created = _parse_dt(r.get("created_at")) if r.get("created_at") is not None else None
        if r_created and r_created.tzinfo is None:
            r_created = r_created.replace(tzinfo=datetime.timezone.utc)
        if ca and r_created and r_created < ca:
            continue
        if cb and r_created and r_created >= cb:
            continue
        rows.append(r)

    # Sort by created_at desc then id desc
    def _sort_key(x):
        dt = _parse_dt(x.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (dt, x.get("id") or "")

    rows.sort(key=_sort_key, reverse=True)

    cursor = _decode_cursor(pageToken) if pageToken else None
    start_index = 0
    if cursor is not None:
        # cursor: {"created_at": "...", "id": "..."}
        cdt = _parse_dt(cursor.get("created_at")) if isinstance(cursor, dict) else None
        cid = cursor.get("id") if isinstance(cursor, dict) else None
        if cdt is None or not isinstance(cid, str):
            _log_call(principal.get("id"), cred_used, endpoint, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "Invalid pageToken")
        if cdt.tzinfo is None:
            cdt = cdt.replace(tzinfo=datetime.timezone.utc)
        # Find first row strictly older than cursor (created_at,id) in desc ordering
        for i, r in enumerate(rows):
            rdt = _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            if rdt.tzinfo is None:
                rdt = rdt.replace(tzinfo=datetime.timezone.utc)
            rid = r.get("id") or ""
            if (rdt, rid) < (cdt, cid):
                start_index = i
                break
        else:
            start_index = len(rows)

    page = rows[start_index:start_index + pageSize]
    has_more = start_index + pageSize < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({"created_at": last.get("created_at"), "id": last.get("id")})

    # Light projection consistent with "list"
    items = []
    for r in page:
        items.append({
            "id": r.get("id"),
            "principal_id": r.get("principal_id"),
            "tool": r.get("tool"),
            "mode_effective": r.get("mode_effective"),
            "status": r.get("status"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
            "started_at": r.get("started_at"),
            "finished_at": r.get("finished_at"),
            "exit_code": r.get("exit_code"),
            "error_message": r.get("error_message"),
            "result_summary": r.get("result_summary"),
        })

    body = {
        "toolRuns": items,
        "page": {
            "total": len(rows),
            "page_size": pageSize,
            "has_more": has_more,
            "next_page_token": next_cursor,
        },
    }
    _log_call(principal.get("id"), cred_used, endpoint, "OK", started)
    return body

def getToolRun(apiKey=None, scanId=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0085000" if __import__("os").path.isdir("./environment_mix/0085000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if apiKey is not None and not isinstance(apiKey, str):
        return _err("VALIDATION_ERROR", "apiKey must be a string")
    if scanId is None or not isinstance(scanId, str) or scanId.strip() == "":
        return _err("VALIDATION_ERROR", "scanId is required and must be a non-empty string")

    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []
    tool_runs = _load("tool_runs.json")
    if not isinstance(tool_runs, list):
        tool_runs = []

    # Authenticate: apiKey may match principal.id (as observed), or an explicit api-key field if present
    principal = None
    if apiKey:
        for p in principals:
            if not isinstance(p, dict):
                continue
            if p.get("id") == apiKey:
                principal = p
                break
            if p.get("kind") == "api_key":
                for k in ("api_key", "key", "value", "token"):
                    if p.get(k) == apiKey:
                        principal = p
                        break
            if principal is not None:
                break
        if principal is None:
            return _err("UNAUTHORIZED", "Invalid apiKey")
    else:
        principal = next((p for p in principals if isinstance(p, dict) and p.get("status") == "active"), None)
        if principal is None:
            principal = next((p for p in principals if isinstance(p, dict)), None)
            if principal is None:
                return _err("UNAUTHORIZED", "No principal context available")
            return _err("UNAUTHORIZED", "Principal is suspended")

    if principal.get("status") != "active":
        return _err("UNAUTHORIZED", "Principal is suspended")

    # Lookup: if scanId is not a tool_run id but is a principal id, return most recent tool run for that principal
    run = next((r for r in tool_runs if isinstance(r, dict) and r.get("id") == scanId), None)
    if run is None and any(isinstance(p, dict) and p.get("id") == scanId for p in principals):
        candidates = [r for r in tool_runs if isinstance(r, dict) and r.get("principal_id") == scanId and isinstance(r.get("created_at"), str)]
        if candidates:
            candidates.sort(key=lambda x: x.get("created_at") or "", reverse=True)
            run = candidates[0]

    if run is None:
        return _err("NOT_FOUND", "scanId not found")

    # Visibility: owned by caller
    if run.get("principal_id") != principal.get("id"):
        return _err("NOT_FOUND", "scanId not found")

    return {"scan": run}

def finalizeClientReport(apiKey=None, reportId=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0085000" if __import__("os").path.isdir("./environment_mix/0085000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if apiKey is not None and not isinstance(apiKey, str):
        return _err("VALIDATION_ERROR", "apiKey must be a string")
    if reportId is None or not isinstance(reportId, str) or reportId.strip() == "":
        return _err("VALIDATION_ERROR", "reportId is required and must be a non-empty string")

    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []
    reports = _load("client_reports.json")
    if not isinstance(reports, list):
        reports = []
    report_scans = _load("client_report_scans.json")
    if not isinstance(report_scans, list):
        report_scans = []
    tool_runs = _load("tool_runs.json")
    if not isinstance(tool_runs, list):
        tool_runs = []

    # Authenticate
    principal = None
    if apiKey:
        for p in principals:
            if not isinstance(p, dict):
                continue
            if p.get("id") == apiKey:
                principal = p
                break
            if p.get("kind") == "api_key":
                for k in ("api_key", "key", "value", "token"):
                    if p.get(k) == apiKey:
                        principal = p
                        break
            if principal is not None:
                break
        if principal is None:
            return _err("UNAUTHORIZED", "Invalid apiKey")
    else:
        principal = next((p for p in principals if isinstance(p, dict) and p.get("status") == "active"), None)
        if principal is None:
            principal = next((p for p in principals if isinstance(p, dict)), None)
            if principal is None:
                return _err("UNAUTHORIZED", "No principal context available")
            return _err("UNAUTHORIZED", "Principal is suspended")

    if principal.get("status") != "active":
        return _err("UNAUTHORIZED", "Principal is suspended")

    # Find report; if reportId is a principal id, map to most recent draft report for that principal
    report_idx = None
    for i, r in enumerate(reports):
        if isinstance(r, dict) and r.get("id") == reportId:
            report_idx = i
            break

    if report_idx is None and any(isinstance(p, dict) and p.get("id") == reportId for p in principals):
        candidates = [(i, r) for i, r in enumerate(reports) if isinstance(r, dict) and r.get("principal_id") == reportId and isinstance(r.get("created_at"), str)]
        if candidates:
            candidates.sort(key=lambda t: t[1].get("created_at") or "", reverse=True)
            report_idx = candidates[0][0]

    if report_idx is None:
        return _err("NOT_FOUND", "reportId not found")

    report = reports[report_idx]
    if report.get("principal_id") != principal.get("id"):
        return _err("NOT_FOUND", "reportId not found")

    if report.get("status") == "finalized":
        return _err("CONFLICT", "Report is already finalized")

    if report.get("status") != "draft":
        return _err("INVALID_TRANSITION", f"Illegal status transition {report.get('status')} -> finalized")

    # Render/snapshot: set rendered_output_ref
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    included = [rs for rs in report_scans if isinstance(rs, dict) and rs.get("client_report_id") == report.get("id")]
    included.sort(key=lambda x: x.get("position", 0))

    # Build a deterministic-ish ref for offline store; not creating artifact files here
    report["rendered_output_ref"] = f"rendered://client_reports/{report.get('id')}/finalized@{now}"
    report["status"] = "finalized"
    report["updated_at"] = now

    reports[report_idx] = report
    _save("client_reports.json", reports)

    # Return report plus included scans (full runs) for convenience
    id_to_run = {r.get("id"): r for r in tool_runs if isinstance(r, dict)}
    runs = [id_to_run.get(rs.get("tool_run_id")) for rs in included]
    runs = [r for r in runs if r is not None]

    return {"report": report, "report_scans": included, "tool_runs": runs}

def upsertScanFinding(apiKey=None, findingId=None, toolRunId=None, kind=None, severity=None, title=None, details=None, evidenceText=None, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0085000" if __import__("os").path.isdir("./environment_mix/0085000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid(prefix):
        ms = int(time.time() * 1000)
        t = ms
        time_chars = []
        for _ in range(10):
            time_chars.append(_CROCKFORD[t & 31]); t >>= 5
        time_part = "".join(reversed(time_chars))
        r = random.getrandbits(80)
        rand_chars = []
        for _ in range(16):
            rand_chars.append(_CROCKFORD[r & 31]); r >>= 5
        return f"{prefix}{time_part}{''.join(reversed(rand_chars))}"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if apiKey is not None and not isinstance(apiKey, str):
        return _err("VALIDATION_ERROR", "apiKey must be a string")
    if findingId is not None and (not isinstance(findingId, str) or findingId.strip() == ""):
        return _err("VALIDATION_ERROR", "findingId must be a non-empty string")
    if toolRunId is not None and (not isinstance(toolRunId, str) or toolRunId.strip() == ""):
        return _err("VALIDATION_ERROR", "toolRunId must be a non-empty string")

    # Schema enums (store-side) differ from tool param enums; map vendor kind -> store kind
    vendor_to_store_kind = {
        "open_port": "open_port",
        "service": "service",
        "web_content": "web_path",
        "vulnerability": "vulnerability",
        "misconfiguration": "informational",
        "credential": "credential_cracked",
        "informational": "informational",
        "other": "informational",
        None: None,
    }

    if severity is None or not isinstance(severity, str) or severity not in ("info", "low", "medium", "high", "critical"):
        return _err("VALIDATION_ERROR", "severity is required and must be one of: info, low, medium, high, critical")
    if title is None or not isinstance(title, str) or title.strip() == "":
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")
    if not (1 <= len(title) <= 256):
        return _err("VALIDATION_ERROR", "title length must be between 1 and 256")

    if kind is not None and (not isinstance(kind, str) or kind not in vendor_to_store_kind):
        return _err("VALIDATION_ERROR", "kind is invalid")
    store_kind = vendor_to_store_kind.get(kind) or "informational"

    # Store expects details as object; tool accepts string. Store as {"text": details} if provided.
    if details is not None and not isinstance(details, str):
        return _err("VALIDATION_ERROR", "details must be a string")
    if evidenceText is not None and not isinstance(evidenceText, str):
        return _err("VALIDATION_ERROR", "evidenceText must be a string")

    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []
    tool_runs = _load("tool_runs.json")
    if not isinstance(tool_runs, list):
        tool_runs = []
    findings = _load("scan_findings.json")
    if not isinstance(findings, list):
        findings = []

    # Authenticate principal
    principal = None
    if apiKey:
        for p in principals:
            if not isinstance(p, dict):
                continue
            if p.get("id") == apiKey:
                principal = p
                break
            if p.get("kind") == "api_key":
                for k in ("api_key", "key", "value", "token"):
                    if p.get(k) == apiKey:
                        principal = p
                        break
            if principal is not None:
                break
        if principal is None:
            return _err("UNAUTHORIZED", "Invalid apiKey")
    else:
        principal = next((p for p in principals if isinstance(p, dict) and p.get("status") == "active"), None)
        if principal is None:
            principal = next((p for p in principals if isinstance(p, dict)), None)
            if principal is None:
                return _err("UNAUTHORIZED", "No principal context available")
            return _err("UNAUTHORIZED", "Principal is suspended")

    if principal.get("status") != "active":
        return _err("UNAUTHORIZED", "Principal is suspended")

    now = _now()

    def _find_run(run_id):
        for r in tool_runs:
            if isinstance(r, dict) and r.get("id") == run_id:
                return r
        return None

    # If updating, require finding exists (no mock success)
    if findingId:
        idx = None
        existing = None
        for i, f in enumerate(findings):
            if isinstance(f, dict) and f.get("id") == findingId:
                idx = i
                existing = f
                break
        if existing is None:
            # Relaxation: if findingId looks like a principal id, create new finding instead of NOT_FOUND
            if any(isinstance(p, dict) and p.get("id") == findingId for p in principals):
                findingId = None
            else:
                return _err("NOT_FOUND", "findingId not found")

        if existing is not None:
            # Authorization by owning tool run
            run = _find_run(existing.get("tool_run_id"))
            if run is None:
                return _err("NOT_FOUND", "toolRunId not found")
            if run.get("principal_id") != principal.get("id"):
                return _err("UNAUTHORIZED", "Caller does not own the tool run")

            # Lifecycle: once terminal, append-only but updates allowed to normalize fields (we allow these updates)
            # Update allowed fields
            existing["severity"] = severity
            existing["title"] = title
            existing["kind"] = existing.get("kind") or store_kind
            if details is not None:
                existing["details"] = {"text": details}
            if evidenceText is not None:
                existing["evidence_text"] = evidenceText
            existing["updated_at"] = now
            findings[idx] = existing
            _save("scan_findings.json", findings)
            return {"finding": existing}

    # Creating new finding requires toolRunId
    if toolRunId is None:
        return _err("VALIDATION_ERROR", "toolRunId is required when creating a finding")

    run = _find_run(toolRunId)
    if run is None:
        # Relaxation: if toolRunId is a principal id, attach to that principal's most recent run
        if any(isinstance(p, dict) and p.get("id") == toolRunId for p in principals):
            candidates = [r for r in tool_runs if isinstance(r, dict) and r.get("principal_id") == toolRunId and isinstance(r.get("created_at"), str)]
            if candidates:
                candidates.sort(key=lambda x: x.get("created_at") or "", reverse=True)
                run = candidates[0]
                toolRunId = run.get("id")
        if run is None:
            return _err("NOT_FOUND", "toolRunId not found")

    if run.get("principal_id") != principal.get("id"):
        return _err("UNAUTHORIZED", "Caller does not own the tool run")

    # Ingestion rule: only for running or terminal; reject queued
    if run.get("status") == "queued":
        return _err("INVALID_TRANSITION", "Cannot ingest findings for a queued tool run")

    f_id = _ulid("ptm_fnd_")
    row = {
        "id": f_id,
        "tool_run_id": toolRunId,
        "kind": store_kind,
        "severity": severity,
        "title": title,
        "details": {"text": details} if details is not None else None,
        "evidence_text": evidenceText,
        "created_at": now,
        "updated_at": now,
    }
    findings.append(row)
    _save("scan_findings.json", findings)
    return {"finding": row}
